styles:
.dashboard-list-group-item {
    display: flex;
    align-items: center;
    gap: 10px;
}
.dashboard-notification-title {
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.text-muted {
    white-space: nowrap;
}

body {
    font-family: 'Poppins', sans-serif;
    background: linear-gradient(135deg, #f0f4f8, #d9e2ec);
    margin: 0;
    display: flex;
    flex-direction: column;
    min-height: 100vh;
}
.dark-mode {
    background: linear-gradient(135deg, #2c3e50, #4a5568);
    color: #e9ecef;
}
.navbar {
    background-color: #1976d2;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}
.navbar-brand img {
    width: 40px;
}
.container-error {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 20px;
}
.error-content {
    max-width: 600px;
    padding: 40px;
    background: white;
    border-radius: 15px;
    box-shadow: 0 8px 30px rgba(0, 0, 0, 0.2);
    transition: transform 0.3s ease;
}
.dark-mode .error-content {
    background: #343a40;
    color: #e9ecef;
}
.error-content:hover {
    transform: translateY(-10px);
}
.error-icon {
    font-size: 80px;
    color: #dc3545;
    margin-bottom: 20px;
}
.error-code {
    font-size: 48px;
    font-weight: 700;
    color: #dc3545;
    margin-bottom: 10px;
}
.error-message {
    font-size: 18px;
    color: #555;
    margin-bottom: 30px;
}
.dark-mode .error-message {
    color: #ced4da;
}
.btn-primary {
    background-color: #1976d2;
    border-color: #1976d2;
    padding: 10px 20px;
    font-size: 16px;
}
.btn-primary:hover {
    background-color: #0d47a1;
    border-color: #0d47a1;
}
.footer {
    background-color: rgba(255, 255, 255, 0.9);
    color: #555;
    text-align: center;
    font-size: 12px;
    padding: 10px 0;
    box-shadow: 0 -4px 10px rgba(0, 0, 0, 0.1);
}
.dark-mode .footer {
    background-color: #212529;
    color: #ced4da;
}
@media (max-width: 576px) {
    .error-content {
        padding: 20px;
    }
    .error-icon {
        font-size: 60px;
    }
    .error-code {
        font-size: 36px;
    }
    .error-message {
        font-size: 16px;
    }
}

