    padding: 15px;
    border-radius: 8px;
}
.modal-body iframe {
    width: 100%;
    height: 80vh;
    border: none;
}
.toast-container {
    position: fixed;
    top: 20px;
    right: 20px;
    z-index: 1055;
}

