    padding: 0;
}
.file-list li {
    margin-bottom: 5px;
}
.file-list a {
    color: #0d6efd;
    text-decoration: none;
}
.file-list a:hover {
    text-decoration: underline;
}

.user-profile {
    display: flex;
    align-items: center;
    color: white;
}
.user-profile span {
    margin-right: 15px;
    font-weight: 500;
}
.user-profile .btn {
    margin-left: 10px;
}
.btn-logout {
    background-color: #dc3545;
    border-color: #dc3545;
}
.btn-logout:hover {
    background-color: #b02a37;
    border-color: #b02a37;
}
.hero-image {
    max-width: 300px; /* Giới hạn chiều rộng tối đa của hình ảnh */
    width: 100%; /* Đảm bảo responsive */
    height: auto; /* Giữ tỷ lệ hình ảnh */
    margin: 0 auto; /* Căn giữa */
    transition: transform 0.3s ease; /* Hiệu ứng mượt mà khi hover */
}
.hero-image:hover {
    transform: scale(1.05); /* Phóng to nhẹ khi hover */
}
@media (max-width: 768px) {
    .hero-image {
        max-width: 200px; /* Giảm kích thước trên màn hình nhỏ */
    }
}
@media (max-width: 576px) {
    .user-profile span {
        display: none;
    }
    .user-profile .btn {
        margin-left: 5px;
        padding: 5px 10px;
        font-size: 14px;
    }
    .hero-image {
        max-width: 150px; /* Giảm kích thước hơn nữa trên điện thoại */
    }
}

