.suggestion-entry { margin-bottom: 10px; padding: 8px; border: 1px solid #ccc; border-radius: 4px; }
.loading-spinner {
    display: none;
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border: 4px solid #f3f3f3;
    border-top: 4px solid #007bff;
    border-radius: 50%;
    width: 30px;
    height: 30px;
    animation: spin 1s linear infinite;
}
@keyframes spin {
    0% { transform: translate(-50%, -50%) rotate(0deg); }
    100% { transform: translate(-50%, -50%) rotate(360deg); }
}
.modal-body.loading .loading-spinner {
    display: block;
}
.modal-body.loading form, .modal-body.loading #suggestionsList {
    opacity: 0.5;
    pointer-events: none;
}

.login.disabled {
    opacity: 0.6;
    pointer-events: none;
}
.error-message {
    display: none;
    color: red;
    font-size: 14px;
    margin-bottom: 10px;
}
.logged-in-section {
    text-align: center;
    padding: 40px;
    background-color: #f0f4f8;
    border-radius: 15px;
    width: 100%;
    max-width: 400px;
}
.logged-in-section h2 {
    font-size: 24px;
    color: #333;
    margin-bottom: 20px;
}
.logged-in-section p {
    font-size: 16px;
    color: #555;
    margin-bottom: 30px;
}
.logged-in-section button {
    width: 48%;
    margin: 0 1%;
    padding: 12px;
    background-color: #1976d2;
    color: white;
    font-size: 16px;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s, transform 0.2s;
}
.logged-in-section button:hover {
    background-color: #0d47a1;
    transform: translateY(-2px);
}
.logged-in-section button.logout {
    background-color: #dc3545;
}
.logged-in-section button.logout:hover {
    background-color: #b02a37;
}
